import subprocess, re, json
from pathlib import Path
from difflib import SequenceMatcher

req_dir = Path('/workspace/requirements')
branches = ['upstream/branch-3.4','upstream/branch-3.3','upstream/trunk']
# load commits per branch in reverse chronological order from git log
branch_commits = {}
for br in branches:
    out = subprocess.check_output(['git','-C','/workspace','log','--format=%H\\t%ad\\t%s','--date=short',br], text=True)
    commits=[]
    for line in out.splitlines():
        h,d,s=line.split('\\t',2)
        commits.append({'hash':h,'date':d,'subject':s,'branch':br})
    branch_commits[br]=commits

all_commits=[]
seen=set()
for br in branches:
    for c in branch_commits[br]:
        if c['hash'] not in seen:
            seen.add(c['hash'])
            all_commits.append(c)

# extra special commits found by keyword may already be in all_commits if on fetched branches.

def normalize(text):
    text = text.strip()
    if text.startswith(\"title:\"):
        text = text.split(':',1)[1].strip()
    # trim surrounding quotes
    if (text.startswith(\"'\") and text.endswith(\"'\")) or (text.startswith('\"') and text.endswith('\"')):
        text = text[1:-1]
    text = text.replace(\"''\", \"'\")
    text = re.sub(r'\\s*\\(#\\d+\\)"'$'"', '', text)
    text = re.sub(r'"'^'"\\[["'^'"\\]]+\\]\\s*', '', text)
    text = re.sub(r'\\s+', ' ', text)
    text = text.replace('…', '...')
    text = text.replace('“','\"').replace('”','\"').replace('’',\"'\")
    return text.strip()

# exact normalized subject map
subject_map={}
for c in all_commits:
    norm=normalize(c['subject'])
    subject_map.setdefault(norm, []).append(c)

reqs=[]
for f in sorted(req_dir.glob('*.yaml')):
    text=f.read_text()
    title=re.search(r'"'^title:'"\\s*(.*)"'$'"', text, re.M).group(1).strip()
    reqs.append({'slug':f.stem,'title':normalize(title),'raw_title':title})

special_search = {
    'ec-decoding-concurrent-preads': 'Fix thread safety of EC decoding during concurrent preads',
    'router-mounttable-search-box': \"RBF: Add search box in Router's tab-mounttable web page\",
    'router-rpc-metrics-prometheus': \"RBF: Registry HDFS Router's rpcserver & rpcclient metrics for PrometheusSink.\",
    'rpcmetrics-inflight-handlers': 'RPCMetrics increases the number of handlers in processing.',
}

mapped=[]
unresolved=[]
for r in reqs:
    candidates = subject_map.get(r['title'], [])
    # exact normalized match with no title punctuation differences
    if not candidates:
        # prefix/variant matching by removing jira ids and punctuation density
        rt = re.sub(r'"'^[A-Z]+-'"\\d+\\.?\\s*', '', r['title'])
        alt = []
        for c in all_commits:
            cs = normalize(c['subject'])
            cst = re.sub(r'"'^[A-Z]+-'"\\d+\\.?\\s*', '', cs)
            if rt == cst:
                alt.append(c)
        candidates = alt
    if not candidates and r['slug'] in special_search:
        key = special_search[r['slug']]
        candidates = [c for c in all_commits if key in normalize(c['subject'])]
    if not candidates:
        # fuzzy by title similarity over same jira id or all commits for special cases
        jira = re.search(r'([A-Z]+-\\d+)', r['title'])
        pool = all_commits
        if jira:
            pool = [c for c in all_commits if jira.group(1) in c['subject']]
        rt = re.sub(r'"'^[A-Z]+-'"\\d+\\.?\\s*', '', r['title'])
        scored=[]
        for c in pool:
            cst = re.sub(r'"'^[A-Z]+-'"\\d+\\.?\\s*', '', normalize(c['subject']))
            score = SequenceMatcher(None, rt.lower(), cst.lower()).ratio()
            if score > 0.75:
                scored.append((score,c))
        scored.sort(key=lambda x:(-x[0], branches.index(x[1]['branch']) if x[1]['branch'] in branches else 99))
        candidates = [c for _,c in scored[:10]]
    # rank branch preference then newer? Actually prefer branch-3.4, then branch-3.3, then trunk, unless exact revert/addendum unique.
    if candidates:
        def key(c):
            return (branches.index(c['branch']) if c['branch'] in branches else 99, c['date'], c['hash'])
        uniq=[]; hashes=set()
        for c in candidates:
            if c['hash'] not in hashes:
                hashes.add(c['hash']); uniq.append(c)
        uniq.sort(key=key)
        mapped.append({'slug':r['slug'],'title':r['title'],'candidates':uniq[:10]})
    else:
        unresolved.append(r)

print('mapped', len(mapped), 'unresolved', len(unresolved))
for r in unresolved:
    print('UNRESOLVED', r['slug'], r['title'])
# show ambiguous counts
amb=[m for m in mapped if len(m['candidates'])>1]
print('ambiguous', len(amb))
for m in amb[:80]:
    print('AMB', m['slug'])
    for c in m['candidates'][:5]:
        print(' ', c['branch'], c['date'], c['hash'][:10], c['subject'])
Path('/tmp/req_commit_map_candidates.json').write_text(json.dumps(mapped, indent=2))
