@Private
@Unstable
public class LeafQueue extends AbstractLeafQueue {
  private static final Logger LOG =
      LoggerFactory.getLogger(LeafQueue.class);

  public LeafQueue(CapacitySchedulerContext csContext,
      String queueName, CSQueue parent, CSQueue old) throws IOException {
    this(csContext, queueName, parent, old, false);
  }

  public LeafQueue(CapacitySchedulerContext csContext,
      String queueName, CSQueue parent, CSQueue old, boolean isDynamic)
      throws IOException {
    this(createQueueContext(csContext, null), queueName, parent, old,
        isDynamic);
  }

  public LeafQueue(CapacitySchedulerContext csContext,
      CapacitySchedulerConfiguration configuration,
      String queueName, CSQueue parent, CSQueue old) throws IOException {
    this(csContext, configuration, queueName, parent, old, false);
  }

  public LeafQueue(CapacitySchedulerContext csContext,
      CapacitySchedulerConfiguration configuration,
      String queueName, CSQueue parent, CSQueue old, boolean isDynamic)
      throws IOException {
    this(createQueueContext(csContext, configuration), queueName, parent, old,
        isDynamic);
  }

  public LeafQueue(CapacitySchedulerQueueContext queueContext,
      String queueName, CSQueue parent, CSQueue old) throws IOException {
    this(queueContext, queueName, parent, old, false);
  }

  public LeafQueue(CapacitySchedulerQueueContext queueContext,
      String queueName, CSQueue parent, CSQueue old, boolean isDynamic) throws
      IOException {
    super(queueContext, queueName, parent, old, isDynamic);

    setupQueueConfigs(queueContext.getClusterResource());
  }

  private static CapacitySchedulerQueueContext createQueueContext(
      CapacitySchedulerContext csContext,
      CapacitySchedulerConfiguration configuration) {
    CapacitySchedulerQueueContext queueContext =
        new CapacitySchedulerQueueContext(csContext);
    if (configuration != null) {
      for (Map.Entry<String, String> entry : configuration) {
        queueContext.setConfigurationEntry(entry.getKey(), entry.getValue());
      }
    }
    return queueContext;
  }
}

