  private Iterator<FileStatus> getNextIterator() throws IOException {
    fetchBatchesAsync();
    try {
      Object obj = null;
      while (obj == null
          && (!isIterationComplete || !iteratorsQueue.isEmpty())) {
        obj = iteratorsQueue.poll(POLL_WAIT_TIME_IN_MS, TimeUnit.MILLISECONDS);
